#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <string>
#include <vector>
#include <sstream>
#include <iostream>
#include <cstdint>
using namespace std;

static string fmt(float v){ ostringstream os; os<<v; return os.str(); }
static float nextf(float x,int dir){ return nextafterf(x, dir>0? INFINITY : -INFINITY); }

struct Obs{ float x; string s; };

int main(int argc,char**argv){
    // argv[1]=file argv[2]=column(1-based within the 13, i.e. 11,12,13) argv[3]=nominal const
    const char* file=argv[1]; int col=atoi(argv[2]); double nom=atof(argv[3]);
    vector<Obs> obs;
    FILE*f=fopen(file,"r"); char line[512];
    while(fgets(line,sizeof line,f)){
        // fields: X then 13 values
        vector<string> t; char*p=strtok(line," \n"); while(p){t.push_back(p);p=strtok(0," \n");}
        if(t.size()!=14) { fprintf(stderr,"bad line %zu\n",t.size()); return 1;}
        Obs o; o.x=strtof(t[0].c_str(),0); o.s=t[col];
        obs.push_back(o);
    }
    fclose(f);
    printf("obs=%zu col=%d nominal=%g\n",obs.size(),col,nom);
    // build float candidate window
    float lo=(float)(nom-1e-5*fabs(nom)/0.299*0.299); // ~1e-5 abs
    lo=(float)(nom-1e-5); float hi=(float)(nom+1e-5);
    if(nom<0){ lo=(float)(nom-1e-5); hi=(float)(nom+1e-5);}    
    int nc=0,nfit=0; float bestc=0; 
    vector<float> fits;
    for(float c=lo; c<=hi; c=nextf(c,1)){
        nc++;
        bool ok=true;
        for(auto&o:obs){ float r=c*o.x; if(fmt(r)!=o.s){ok=false;break;} }
        if(ok){ fits.push_back(c); }
    }
    printf("float candidates scanned=%d  fitting=%zu\n",nc,fits.size());
    for(float c:fits){ uint32_t b; memcpy(&b,&c,4); printf("  FLOAT fit c=%.9g bits=0x%08x  (== (float)%.17g ? %s)\n",c,b,nom, (c==(float)nom)?"yes":"no"); }
    // double mode with the decimal literal
    {
        double d=nom; int bad=0; string firstbad;
        for(auto&o:obs){ float r=(float)(d*(double)o.x); if(fmt(r)!=o.s){ if(!bad) { char buf[256]; snprintf(buf,sizeof buf,"x=%.9g oracle=%s doubleMode=%s",o.x,o.s.c_str(),fmt(r).c_str()); firstbad=buf;} bad++; } }
        printf("DOUBLE-literal mode (%.17g): mismatches=%d/%zu  %s\n",d,bad,obs.size(),firstbad.c_str());
    }
    // long double mode
    {
        long double d=(long double)nom; int bad=0; string firstbad;
        for(auto&o:obs){ float r=(float)(d*(long double)o.x); if(fmt(r)!=o.s){ if(!bad){char buf[256]; snprintf(buf,sizeof buf,"x=%.9g oracle=%s ldMode=%s",o.x,o.s.c_str(),fmt(r).c_str()); firstbad=buf;} bad++; } }
        printf("LONGDOUBLE-literal mode: mismatches=%d/%zu %s\n",bad,obs.size(),firstbad.c_str());
    }
    return 0;
}
