#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <string>
#include <vector>
#include <sstream>
#include <iostream>
using namespace std;

// pinned float constants
static const float Y0=0.299f, Y1=0.587f, Y2=0.114f;
static const float U0=0.147f, U1=0.289f, U2=0.436f;
static const float V0=0.615f, V1=0.515f, V2=0.100f;

#define NY 12
static float yv(int k,float r,float g,float b){
 switch(k){
  case 0: return ((Y0*r)+(Y1*g))+(Y2*b);                       // float LR  (claimed)
  case 1: return (Y0*r)+((Y1*g)+(Y2*b));                       // float RL
  case 2: return ((Y0*r)+(Y2*b))+(Y1*g);                       // reorder
  case 3: return (float)((((double)Y0*(double)r)+((double)Y1*(double)g))+((double)Y2*(double)b)); // dbl acc, float consts
  case 4: return (float)((0.299*(double)r+0.587*(double)g)+0.114*(double)b);                      // all-double literals
  case 5: return fmaf(Y2,b,fmaf(Y1,g,Y0*r));                   // fully contracted
  case 6: return fmaf(Y1,g,Y0*r)+(Y2*b);                       // contract 1st add only
  case 7: return fmaf(Y2,b,((Y0*r)+(Y1*g)));                   // contract 2nd add only
  case 8: return ((r*Y0)+(g*Y1))+(b*Y2);                       // mult operand order swap
  case 9: return (float)((((long double)Y0*r)+((long double)Y1*g))+((long double)Y2*b)); // ld acc
  case 10:return ((Y0*r)+(Y1*g))+(Y2*b);                       // dup of 0 (sanity)
  case 11:return fmaf(Y0,r,fmaf(Y1,g,Y2*b));                   // contracted RL
 }
 return 0;
}
#define NU 12
static float uv(int k,float r,float g,float b){
 switch(k){
  case 0: return (((-U0)*r)-(U1*g))+(U2*b);                    // claimed LR
  case 1: return ((U2*b)-(U0*r))-(U1*g);                       // b-first
  case 2: return (U2*b)-((U0*r)+(U1*g));                       // grouped subtrahend
  case 3: return ((-U0)*r)+(((-U1)*g)+(U2*b));                 // right assoc
  case 4: return (float)(((-(double)U0*(double)r)-((double)U1*(double)g))+((double)U2*(double)b)); // dbl acc
  case 5: return (float)((-0.147*(double)r-0.289*(double)g)+0.436*(double)b);                     // all-double literals
  case 6: return fmaf(U2,b,fmaf(-U1,g,(-U0)*r));               // contracted
  case 7: return -((U0*r)+(U1*g))+(U2*b);                      // negated group  (should == case0)
  case 8: return ((U2*b)-(U1*g))-(U0*r);                       // another order
  case 9: return (0.0f-(U0*r)-(U1*g))+(U2*b);                  // 0 - a form
  case 10:return ((-U0)*r-(U1*g))+(U2*b);                      // same as 0
  case 11:return fmaf(U2,b,((-U0)*r-(U1*g)));                  // contract last only
 }
 return 0;
}
#define NV 12
static float vv(int k,float r,float g,float b){
 switch(k){
  case 0: return ((V0*r)-(V1*g))-(V2*b);                       // claimed LR
  case 1: return (V0*r)-((V1*g)+(V2*b));                       // grouped
  case 2: return ((V0*r)-(V2*b))-(V1*g);                       // reorder
  case 3: return (float)((((double)V0*(double)r)-((double)V1*(double)g))-((double)V2*(double)b)); // dbl acc
  case 4: return (float)((0.615*(double)r-0.515*(double)g)-0.100*(double)b);                      // all-double literals
  case 5: return fmaf(-V2,b,fmaf(-V1,g,V0*r));                 // contracted
  case 6: return ((V0*r)+((-V1)*g))+((-V2)*b);                  // signs folded, all adds
  case 7: return (V0*r)-((V2*b)+(V1*g));
  case 8: return (float)((((long double)V0*r)-((long double)V1*g))-((long double)V2*b));
  case 9: return fmaf(-V1,g,V0*r)-(V2*b);
  case 10:return fmaf(-V2,b,((V0*r)-(V1*g)));
  case 11:return ((V0*r)-(V1*g))-(0.1f*b);                     // 0.1f vs 0.100f identical
 }
 return 0;
}
static string fs(float v){ ostringstream os; os<<v; return os.str(); }

int main(int argc,char**argv){
    // mode: "emit" -> read triples (3 decimal strings per line) print all variants per line
    char line[512];
    while(fgets(line,sizeof line,stdin)){
        char*p=strtok(line," \t\n"); if(!p)continue; float r=strtof(p,0);
        p=strtok(0," \t\n"); float g=strtof(p,0);
        p=strtok(0," \t\n"); float b=strtof(p,0);
        string out;
        for(int k=0;k<NY;k++){ out+=fs(yv(k,r,g,b)); out+=' '; }
        for(int k=0;k<NU;k++){ out+=fs(uv(k,r,g,b)); out+=' '; }
        for(int k=0;k<NV;k++){ out+=fs(vv(k,r,g,b)); if(k<NV-1) out+=' '; }
        printf("%s\n",out.c_str());
    }
    return 0;
}
