#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <random>
#include <cstdint>
using namespace std;
static std::mt19937_64 rng(987654321ULL);
static float rf(int elo,int ehi){
    uint32_t mant=rng()&0x7FFFFFu; int e=elo+(int)(rng()%(unsigned)(ehi-elo+1));
    uint32_t bits=((uint32_t)(e+127)<<23)|mant; if(rng()&1) bits|=0x80000000u;
    float f; memcpy(&f,&bits,4); return f;
}
static float pert(float x,int k){ for(int i=0;i<abs(k);i++) x=nextafterf(x,k>0?INFINITY:-INFINITY); return x; }
static void emit(float r,float g,float b){
    if(!isfinite(r)||!isfinite(g)||!isfinite(b))return;
    if((r!=0&&fabsf(r)<1e-30f)||(g!=0&&fabsf(g)<1e-30f)||(b!=0&&fabsf(b)<1e-30f))return;
    if(fabsf(r)>1e30f||fabsf(g)>1e30f||fabsf(b)>1e30f)return;
    printf("%.9g %.9g %.9g\n",r,g,b);
}
int main(int argc,char**argv){
    int N=atoi(argv[1]);
    const float Y0=0.299f,Y1=0.587f,Y2=0.114f;
    const float U0=0.147f,U1=0.289f,U2=0.436f;
    const float V0=0.615f,V1=0.515f,V2=0.100f;
    // 1) plain random, wide exponent
    for(int i=0;i<N/4;i++) emit(rf(-20,20),rf(-20,20),rf(-20,20));
    // 2) plain random, narrow (typical color range 0..1-ish)
    for(int i=0;i<N/4;i++){
        float r=(float)((double)(rng()%2000001)/1000000.0-0.5);
        float g=(float)((double)(rng()%2000001)/1000000.0-0.5);
        float b=(float)((double)(rng()%2000001)/1000000.0-0.5);
        emit(r,g,b);
    }
    // 3) cancellation-amplified for each of y,u,v: solve 3rd channel, perturb
    int M=N/4/6+1;
    for(int i=0;i<M;i++){
        float r=rf(-8,8),g=rf(-8,8);
        // y: solve b
        float b=(float)(-((double)Y0*r+(double)Y1*g)/(double)Y2);
        for(int k=-3;k<=3;k++) emit(r,g,pert(b,k));
        // u: -U0 r - U1 g + U2 b = 0
        b=(float)(((double)U0*r+(double)U1*g)/(double)U2);
        for(int k=-3;k<=3;k++) emit(r,g,pert(b,k));
        // v: V0 r - V1 g - V2 b = 0
        b=(float)(((double)V0*r-(double)V1*g)/(double)V2);
        for(int k=-3;k<=3;k++) emit(r,g,pert(b,k));
        // also solve for g given r,b
        float rr=rf(-8,8),bb=rf(-8,8);
        float gg=(float)(-((double)Y0*rr+(double)Y2*bb)/(double)Y1);
        for(int k=-3;k<=3;k++) emit(rr,pert(gg,k),bb);
        gg=(float)((-(double)U0*rr+(double)U2*bb)/(double)U1);
        for(int k=-3;k<=3;k++) emit(rr,pert(gg,k),bb);
        gg=(float)(((double)V0*rr-(double)V2*bb)/(double)V1);
        for(int k=-3;k<=3;k++) emit(rr,pert(gg,k),bb);
    }
    // 4) structured: 0,1,-1,0.5, powers of two, ties
    static const float sp[]={0.0f,-0.0f,1.0f,-1.0f,0.5f,-0.5f,0.25f,2.0f,-2.0f,3.0f,0.1f,0.2f,0.3f,0.4f,0.6f,0.7f,0.8f,0.9f,
        1.0f/3,2.0f/3,1e-3f,1e3f,255.0f,128.0f,-255.0f,16777216.0f,8388608.0f,1.0f/1024,100.0f,0.299f,0.587f,0.114f,0.436f};
    int ns=sizeof(sp)/sizeof(sp[0]);
    for(int a=0;a<ns;a++)for(int c=0;c<ns;c++)for(int d=0;d<ns;d++) emit(sp[a],sp[c],sp[d]);
    return 0;
}
